mapper.select:
SELECT * FROM tt_task_definition
WHERE tenant_id = #{tenantId}
AND EXISTS (
    SELECT 1 FROM tt_task_participant p
    WHERE p.definition_id = tt_task_definition.definition_id
      AND p.instance_id IS NULL
      AND p.principal_type = 'USER'
      AND p.principal_id = #{participantPrincipalId}
)
AND scenario_key = #{scenarioKey}
AND control_state = #{controlState}

    AND (updated_at, definition_id) < (#{cursorUpdatedAt}, #{cursorDefinitionId})

ORDER BY updated_at DESC, definition_id DESC
LIMIT #{limit}
